    'cyber_security-cryptography-s1-set3' => [
        [
            'text' => 'Explain Public Key Infrastructure (PKI): Root Certificate Authorities (CAs), Intermediate CAs, Leaf Certificates, Certificate Revocation Lists (CRL), and Online Certificate Status Protocol (OCSP).',
            'category' => 'technical',
            'duration_seconds' => 180,
            'note' => 'Hierarchical trust tree. Root CA self-signs and is kept offline; Intermediate CAs issue leaf certificates; CRL publishes periodic list of revoked cert serial numbers; OCSP provides real-time status query; OCSP Stapling allows server to include cached CA status in TLS handshake.',
        ],
        [
